/*
 * Space kit, the init-time and per-change half (S095 P1; S095_P1_IMPLEMENTATION.md
 * S6, §S18): the feed setup and its write-head limit, the share-cut rule,
 * the dry ramp, the export helpers, the ring clear and the drain's start.
 * Build: an ordinary -O2 source. Nothing here runs per frame; sk_feedBegin()
 * runs once per type change, the rest at most once per block. Every
 * function is noinline: inlined into a caller in a fast-math (-Ofast) file
 * it would be compiled there at -Ofast and grow (S095 P1 rework: the feed
 * setup reached 2.8 KB inside crumpBit_init()). The per-frame half is
 * SpaceKitDsp.c.
 */

#include <string.h>

/* The end-fade reciprocal for a head of `left` samples (min(882, left/4)). */
static float sk_fadeInv(uint32_t left)
{
    const uint32_t q = left / 4u;

    return 1.0f / (float)((q > SK_FEED_FADE_MAX) ? SK_FEED_FADE_MAX
                                                 : (q == 0u ? 1u : q));
}

__attribute__((noinline, cold)) void sk_feedBegin(const fx_share_t *share,
                                                  const fxbuf_handoff_t *h,
                                                  uint8_t owner)
{
    sk_ctl_t *c;
    /* nseg: the valid segments; the head is the first of them. */
    uint32_t nseg = 0u;
    uint32_t esize;
    uint32_t sb;
    uint32_t i;

    if (!share || !share->base || share->bytes < SK_PREFIX_BYTES)
        return;
    c = sk_ctl(share);
    /* 1. The block: this owner, no feed. */
    memset(c, 0, sizeof(*c));
    c->magic = SK_CTL_MAGIC | (uint32_t)owner;
    if (!h || (h->state_flags & FXBUF_STATE_EFFECT_WRITTEN) == 0u)
        return;
    c->dry_from_q7 = (uint8_t)(((uint32_t)h->effect_dry_uq15 * 128u +
                                0x4000u) >> 15);
    c->dry_blocks = SK_DRY_RAMP_BLOCKS;
    esize = (uint32_t)h->effect_bits / 8u;
    sb = h->effect_stride;
    /*
     * 2. A wrap domain this reader can trust, inside the usable share, and
     * at least 64 samples long (a block's head moves at most 33 samples, so
     * sk_feedMix() splits a block at one wrap at most).
     */
    if ((esize != 1u && esize != 2u) || sb == 0u || (sb % esize) != 0u ||
        h->effect_wrap_bytes < 64u * sb ||
        h->effect_wrap_offset < SK_PREFIX_BYTES ||
        h->effect_wrap_offset + h->effect_wrap_bytes > share->bytes)
        return;
    /* 3. The segments (oldest byte, one past the newest; the lane rule). */
    for (i = 0u; i < FXBUF_EFFECT_POINTER_COUNT; i++) {
        const uint32_t slot = FXBUF_HANDOFF_EFFECT_POINTER_BASE + i;
        const uint32_t s = h->read_offset[slot];
        const uint32_t e = h->write_offset[slot];
        uint32_t rs;
        uint32_t re;
        uint32_t bytes;

        if (s == FXBUF_OFFSET_NONE || e == FXBUF_OFFSET_NONE ||
            s < h->effect_wrap_offset || e < h->effect_wrap_offset)
            continue;
        rs = s - h->effect_wrap_offset;
        re = e - h->effect_wrap_offset;
        if (rs >= h->effect_wrap_bytes || re > h->effect_wrap_bytes)
            continue;
        re %= h->effect_wrap_bytes;
        bytes = (re >= rs) ? re - rs : re + h->effect_wrap_bytes - rs;
        if (bytes < sb)
            continue;
        if (nseg++ != 0u)
            continue;
        /* The first segment is the head, read in place. */
        c->wrap_off = h->effect_wrap_offset;
        c->wrap_elems = h->effect_wrap_bytes / esize;
        c->pos = (rs / esize + ((i * esize) % sb) / esize) % c->wrap_elems;
        c->left = bytes / sb;
        c->stride = (uint8_t)(sb / esize);
        c->end = h->effect_wrap_offset + re;
    }
    if (nseg == 0u)
        return;
    /* One line of a ring plays at x 2 and fades: a ring line ends abruptly. */
    if (nseg > 2u)
        c->flags |= SK_FEED_FADE;
    if (esize == 2u)
        c->flags |= SK_FEED_S16;
    /* 4. Step, gain, ceiling, fade, the feeding flag and the lock. */
    c->step_q16 = (uint32_t)(((uint32_t)h->effect_speed_uq15 * 2u *
                              (uint32_t)h->effect_rate_hz) / 44108u);
    c->step_q16 = (c->step_q16 == 0u || c->step_q16 > 65536u) ? 65536u
                                                               : c->step_q16;
    c->gain = (float)h->effect_feed_gain_uq15 * (1.0f / 32768.0f) *
              ((esize == 2u) ? (1.0f / 32768.0f) : (1.0f / 128.0f)) *
              ((nseg > 2u) ? 2.0f : 1.0f);
    {
        const uint32_t ceil_samples = (SK_FEED_CEIL_FRAMES >> 4) *
                                      (c->step_q16 >> 12);

        if (c->left > ceil_samples) {
            c->left = ceil_samples;
            c->flags |= SK_FEED_FADE;
        }
    }
    c->fade_inv = (c->flags & SK_FEED_FADE) ? sk_fadeInv(c->left) : 1.0f;
    c->feeding = (uint8_t)(c->left != 0u);
    if (c->feeding)
        effects_setFeedSlotLock(1u);
}

__attribute__((noinline, cold)) uint32_t sk_feedEnd(const fx_share_t *share,
                                                   uint8_t owner)
{
    if (!share || !sk_owned(share, owner) || !sk_ctl(share)->feeding)
        return 0u;
    return sk_ctl(share)->end;
}

/* Two blocks: a block's writes come before the feed reads that block. */
#define SK_FEED_MARGIN 64.0f

__attribute__((noinline, cold)) void sk_feedLimit(const fx_share_t *share,
                                                  uint8_t owner,
                                                  const sk_writer_t *w,
                                                  uint32_t n)
{
    sk_ctl_t *c;
    /* sb: bytes per head sample; dom: the head's wrap domain in bytes. */
    float sb;
    float dom;
    /* a: the next sample's address; j0: its head sample index; fps: output
     * frames per head sample; lim: the samples kept. */
    float a;
    float j0 = 0.0f;
    float fps;
    float lim;
    uint32_t q;

    if (!share || !w || !sk_owned(share, owner) || !sk_ctl(share)->feeding)
        return;
    c = sk_ctl(share);
    sb = (float)(c->stride * ((c->flags & SK_FEED_S16) ? 2u : 1u));
    dom = (float)c->wrap_elems * (sb / (float)c->stride);
    a = (float)c->wrap_off + (float)c->pos * (sb / (float)c->stride);
    fps = 65536.0f / (float)c->step_q16;
    lim = (float)c->left;
    /*
     * Every pair (tail piece p, writer k, writer piece h): the tail in at
     * most two unwrapped pieces [a0, a1); a writer first writes [at, hi)
     * from now, then [lo, at) after its lap (rate 0: [lo, hi) now). In a
     * pair both times are linear in the address x: g(x) = write time -
     * read time - margin, and the first x with g <= 0 is where the tail is
     * cut (the minimum over all pairs).
     */
    for (q = 0u; q < 4u * n; q++) {
        const sk_writer_t *v = &w[q >> 2];
        const uint32_t p = q & 1u;
        const uint32_t h = (q >> 1) & 1u;
        /* The tail piece: before the domain's end, or after its wrap. */
        const float end = (float)c->wrap_off + dom;
        const float a0 = p ? (float)c->wrap_off : a;
        const float pj = p ? (end - a) / sb : 0.0f;
        const float a1 = p ? a0 + ((float)c->left - pj) * sb
                           : ((a + (float)c->left * sb < end)
                                  ? a + (float)c->left * sb : end);
        const float b0 = (float)(h ? v->lo : (v->rate ? v->at : v->lo));
        const float b1 = (float)((h && v->rate) ? v->at : v->hi);
        const float t0 = h ? (float)(v->hi - v->at) / (float)v->rate : 0.0f;
        const float x0 = (a0 > b0) ? a0 : b0;
        const float x1 = (a1 < b1) ? a1 : b1;
        float x;
        float g;
        float dg;

        if (x0 >= x1 || (h && v->rate == 0u))
            continue;
        if (v->rate == 0u) {
            x = x0;
        } else {
            g = t0 + (x0 - b0) / (float)v->rate -
                (pj + (x0 - a0) / sb) * fps - SK_FEED_MARGIN;
            dg = 1.0f / (float)v->rate - fps / sb;
            if (g <= 0.0f)
                x = x0;
            else if (dg < 0.0f && x0 - g / dg < x1)
                x = x0 - g / dg;
            else
                continue;
        }
        j0 = pj + (x - a0) / sb;
        lim = (j0 < lim) ? j0 : lim;
    }
    if (lim >= (float)c->left)
        return;
    c->left = (uint32_t)lim;
    c->flags |= SK_FEED_FADE;
    c->fade_inv = sk_fadeInv(c->left);
    if (c->left == 0u) {
        c->feeding = 0u;
        effects_setFeedSlotLock(0u);
    }
}

__attribute__((noinline, cold)) uint8_t sk_feedCut(const fx_share_t *share,
                                                  uint8_t owner)
{
    sk_ctl_t *c;

    if (!share || !sk_owned(share, owner))
        return 0u;
    c = sk_ctl(share);
    /* The head's whole domain must still be inside the share. */
    if (!c->feeding || c->wrap_off + c->wrap_elems *
        ((c->flags & SK_FEED_S16) ? 2u : 1u) <= share->bytes)
        return 0u;
    c->feeding = 0u;
    effects_setFeedSlotLock(0u);
    return 1u;
}

__attribute__((noinline, cold)) void sk_dryRamp(const fx_share_t *share, uint8_t owner, float target,
                float *d0, float *d1)
{
    sk_ctl_t *c;
    float from;

    *d0 = target;
    *d1 = target;
    if (!share || !sk_owned(share, owner))
        return;
    c = sk_ctl(share);
    if (c->dry_blocks == 0u)
        return;
    from = (float)c->dry_from_q7 * (1.0f / 128.0f);
    /* Linear from the outgoing dry to the target over the ramp's blocks. */
    *d0 = target + (from - target) *
          ((float)c->dry_blocks * (1.0f / (float)SK_DRY_RAMP_BLOCKS));
    c->dry_blocks--;
    *d1 = target + (from - target) *
          ((float)c->dry_blocks * (1.0f / (float)SK_DRY_RAMP_BLOCKS));
}

__attribute__((noinline, cold)) void sk_exportBegin(fxbuf_handoff_t *out, uint32_t wrap_off,
                    uint32_t wrap_bytes, uint8_t bits, uint8_t stride,
                    uint16_t rate_hz, float speed, float dry, float gain)
{
    /* q15: a gain or speed in 0..1.99997 as uQ1.15 (0x8000 = 1.0). */
    float q;

    out->effect_wrap_offset = wrap_off;
    out->effect_wrap_bytes = wrap_bytes;
    out->effect_bits = bits;
    out->effect_stride = stride;
    out->effect_rate_hz = rate_hz;
    q = speed * 32768.0f + 0.5f;
    out->effect_speed_uq15 = (uint16_t)((q > 65535.0f) ? 65535.0f : (q < 0.0f ? 0.0f : q));
    q = dry * 32768.0f + 0.5f;
    out->effect_dry_uq15 = (uint16_t)((q > 65535.0f) ? 65535.0f : (q < 0.0f ? 0.0f : q));
    q = gain * 32768.0f + 0.5f;
    out->effect_feed_gain_uq15 = (uint16_t)((q > 65535.0f) ? 65535.0f : (q < 0.0f ? 0.0f : q));
    out->effect_seg_sides = 0u;
}

__attribute__((noinline, cold)) void sk_exportSeg(fxbuf_handoff_t *out, uint8_t i, uint32_t start,
                  uint32_t end, uint8_t side)
{
    const uint32_t slot = FXBUF_HANDOFF_EFFECT_POINTER_BASE + i;

    if (i >= FXBUF_EFFECT_POINTER_COUNT || start == end)
        return;
    out->read_offset[slot] = start;
    out->write_offset[slot] = end;
    out->effect_seg_sides = (uint8_t)((out->effect_seg_sides &
        ~(FXBUF_SEG_SIDE_MASK << FXBUF_SEG_SIDE_SHIFT(i))) |
        ((side & FXBUF_SEG_SIDE_MASK) << FXBUF_SEG_SIDE_SHIFT(i)));
    out->state_flags |= FXBUF_STATE_EFFECT_WRITTEN;
}

__attribute__((noinline, cold)) void sk_clear(const fx_share_t *share, uint32_t off, uint32_t bytes)
{
    if (!share || !share->base || off >= share->bytes)
        return;
    if (off + bytes > share->bytes)
        bytes = share->bytes - off;
    memset(share->base + off, 0, bytes);
}

__attribute__((noinline, cold)) uint8_t sk_drainBegin(const fx_share_t *share, uint8_t owner)
{
    sk_ctl_t *c;

    if (!share || !sk_owned(share, owner))
        return 0u;
    c = sk_ctl(share);
    c->drain_blocks = 0u;
    c->drain_quiet = 0u;
    return 1u;
}

